package megalodonte.engine.editor;
import javafx.collections.*;
import javafx.scene.canvas.Canvas;
import javafx.scene.control.*;
import javafx.scene.image.Image;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.stage.*;
import megalodonte.engine.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;

/** Bounded tile painting viewport, so long maps never allocate huge canvases. */
final class TileMapEditor {
    private final Game.TileMap map;private final Consumer<Game.TileMap> apply;private final PendingAssets assets;private final Path directory;private final Window owner;
    private final ListView<Game.TileLayer> layers=new ListView<>();private final ComboBox<Integer> brush=new ComboBox<>(),tiles=new ComboBox<>();
    private final FeatureForms.Form geometry=new FeatureForms.Form(),layerForm=new FeatureForms.Form(),tileForm=new FeatureForms.Form();
    private final Canvas canvas=new Canvas(560,400);private final ScrollBar horizontal=new ScrollBar(),vertical=new ScrollBar();private final Label message=new Label();
    private final CheckBox flipH=new CheckBox("Espelhar X"),flipV=new CheckBox("Espelhar Y"),diagonal=new CheckBox("Diagonal");
    private final Map<String,Image> images=new HashMap<>();private Game.TileLayer active;private Integer activeTile;
    TileMapEditor(Game.TileMap target,Consumer<Game.TileMap> apply,PendingAssets assets,Path directory,Window owner){map=Codec.GSON.fromJson(Codec.GSON.toJson(target),Game.TileMap.class);this.apply=apply;this.assets=assets;this.directory=directory;this.owner=owner;}
    private Button button(String caption,Runnable action){var b=new Button(caption);b.setOnAction(e->{try{action.run();}catch(Exception failure){message.setText(failure.getMessage());}});return b;}
    void show(){
        canvas.setId("mapPaint");brush.setId("tileBrush");geometry.text("mapId","ID do mapa",map.id);geometry.text("mapName","Nome",map.name);geometry.text("columns","Colunas",map.columns);geometry.text("rows","Linhas",map.rows);geometry.text("tileWidth","Largura da célula (pixels)",map.tileWidth);geometry.text("tileHeight","Altura da célula (pixels)",map.tileHeight);geometry.text("mapX","Posição X (mundo)",map.x);geometry.text("mapY","Posição Y (mundo)",map.y);geometry.text("unit","Unidades de mundo por pixel",map.unitScale);
        layerForm.text("layerName","Nome da camada","");layerForm.text("layerX","Deslocamento X (pixels)",0);layerForm.text("layerY","Deslocamento Y (pixels, positivo para baixo)",0);layerForm.text("opacity","Opacidade (0 a 1)",1);
        layers.setPrefWidth(160);layers.setItems(FXCollections.observableArrayList(map.layers));layers.setCellFactory(list->new ListCell<>(){@Override protected void updateItem(Game.TileLayer item,boolean empty){super.updateItem(item,empty);setText(empty||item==null?null:item.name);}});
        layers.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{active=b;if(b!=null){layerForm.fields.get("layerName").setText(b.name);layerForm.fields.get("layerX").setText(""+b.offsetX);layerForm.fields.get("layerY").setText(""+b.offsetY);layerForm.fields.get("opacity").setText(""+b.opacity);}draw();});
        horizontal.setMax(Math.max(0,map.columns-28));vertical.setOrientation(javafx.geometry.Orientation.VERTICAL);vertical.setMax(Math.max(0,map.rows-20));horizontal.valueProperty().addListener((o,a,b)->draw());vertical.valueProperty().addListener((o,a,b)->draw());
        brush.setPrefWidth(160);brush.setCellFactory(list->tileCell());brush.setButtonCell(tileCell());tiles.setCellFactory(list->tileCell());tiles.setButtonCell(tileCell());refreshTiles();brush.setValue(0);canvas.setOnMousePressed(e->paint(e.getX(),e.getY(),e.isSecondaryButtonDown()));canvas.setOnMouseDragged(e->paint(e.getX(),e.getY(),e.isSecondaryButtonDown()));
        var painting=new VBox(8,new HBox(6,new Label("Tile"),brush,flipH,flipV,diagonal),new HBox(canvas,vertical),horizontal,new Label("Clique/arraste para pintar; botão direito apaga. A rolagem percorre o mapa."));
        var layerList=new VBox(6,layers,new HBox(6,button("Nova",this::addLayer),button("Excluir",this::deleteLayer)),new HBox(6,button("Subir",()->moveLayer(-1)),button("Descer",()->moveLayer(1))));
        var layerProps=new VBox(6,layerForm.box,button("Aplicar camada",this::saveLayer));
        tileForm.text("asset","Imagem (caminho relativo)","");tileForm.text("sourceX","Recorte X",0);tileForm.text("sourceY","Recorte Y",0);tileForm.text("width","Largura do recorte",map.tileWidth);tileForm.text("height","Altura do recorte",map.tileHeight);
        tiles.valueProperty().addListener((o,a,b)->loadTile(b));var tilePanel=new VBox(8,new Label("Tile ID"),tiles,tileForm.box,new HBox(6,button("Novo tile",this::addTile),button("Excluir tile",this::deleteTile)),button("Importar imagem do tile",this::importImage),button("Aplicar tile",this::saveTile));
        var obstacles=new VBox(8,new Label("Colisores em pixels locais do mapa; aplicados mesmo em áreas sem tiles."));var list=new ListView<Game.Entity>(FXCollections.observableArrayList(map.obstacles));list.setPrefHeight(150);list.setCellFactory(l->new ListCell<>(){@Override protected void updateItem(Game.Entity e,boolean empty){super.updateItem(e,empty);setText(empty||e==null?null:e.name+" • "+e.x+", "+e.y+" • "+e.width+" × "+e.height);}});
        var obstacleForm=new FeatureForms.Form();for(String key:new String[]{"x","y","width","height"})obstacleForm.text(key,key, key.equals("width")||key.equals("height")?32:0);
        obstacleForm.text("polygon","Polígono local em pixels: x,y,x,y… (vazio = retângulo)","");
        list.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b==null)return;obstacleForm.fields.get("polygon").setText(b.colliderPolygon.toString().replace("[","").replace("]",""));obstacleForm.fields.get("x").setText(""+b.x);obstacleForm.fields.get("y").setText(""+b.y);obstacleForm.fields.get("width").setText(""+b.width);obstacleForm.fields.get("height").setText(""+b.height);});
        obstacles.getChildren().addAll(list,obstacleForm.box,new HBox(6,button("Adicionar colisor",()->{var e=new Game.Entity();e.name="Colisor";e.width=e.height=32;map.obstacles.add(e);list.getItems().add(e);list.getSelectionModel().select(e);}),button("Excluir colisor",()->{var e=list.getSelectionModel().getSelectedItem();map.obstacles.remove(e);list.getItems().remove(e);}),button("Aplicar colisor",()->{var e=list.getSelectionModel().getSelectedItem();if(e==null)return;double x=obstacleForm.number("x"),y=obstacleForm.number("y"),w=obstacleForm.number("width"),h=obstacleForm.number("height");if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(w)||!Double.isFinite(h)||w<=0||h<=0)throw new IllegalArgumentException("Geometria inválida.");var polygon=FeatureForms.polygon(obstacleForm.value("polygon"));e.x=x;e.y=y;e.width=w;e.height=h;e.colliderPolygon=polygon;list.refresh();})));
        var tabs=new TabPane(new Tab("Mapa",geometry.box),new Tab("Camadas e pintura",new HBox(10,layerList,painting,layerProps)),new Tab("Tileset",tilePanel),new Tab("Colisores",obstacles));tabs.getTabs().forEach(t->t.setClosable(false));
        var d=new Dialog<Void>();d.initOwner(owner);d.setTitle("Mapa • "+map.name);d.getDialogPane().getButtonTypes().addAll(ButtonType.APPLY,ButtonType.CLOSE);d.getDialogPane().setId("tileMapEditor");((Button)d.getDialogPane().lookupButton(ButtonType.APPLY)).setText("Aplicar");((Button)d.getDialogPane().lookupButton(ButtonType.CLOSE)).setText("Fechar");var scroll=new ScrollPane(tabs);scroll.setFitToWidth(true);scroll.setPrefViewportWidth(1000);scroll.setPrefViewportHeight(560);d.getDialogPane().setContent(new VBox(8,scroll,message));d.getDialogPane().lookupButton(ButtonType.APPLY).addEventFilter(javafx.event.ActionEvent.ACTION,event->{event.consume();try{saveLayer();saveTile();saveGeometry();apply.accept(Codec.GSON.fromJson(Codec.GSON.toJson(map),Game.TileMap.class));message.setText("Mapa aplicado. Salve o projeto.");}catch(Exception failure){message.setText(failure.getMessage());}});
        if(!map.layers.isEmpty())layers.getSelectionModel().selectFirst();if(!map.tiles.isEmpty())tiles.getSelectionModel().selectFirst();d.show();
    }
    private void saveGeometry(){
        int columns=Integer.parseInt(geometry.value("columns")),rows=Integer.parseInt(geometry.value("rows")),tileWidth=Integer.parseInt(geometry.value("tileWidth")),tileHeight=Integer.parseInt(geometry.value("tileHeight"));
        double x=geometry.number("mapX"),y=geometry.number("mapY"),unit=geometry.number("unit");
        if(columns<=0||rows<=0||(long)columns*rows>10000000||tileWidth<=0||tileHeight<=0||!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(unit)||unit<=0)throw new IllegalArgumentException("Dimensões, posição ou escala inválidos (máximo 10 milhões de células).");
        if(columns!=map.columns||rows!=map.rows){for(var layer:map.layers){long[] next=new long[columns*rows];for(int row=0;row<Math.min(rows,map.rows);row++)System.arraycopy(layer.data,row*map.columns,next,row*columns,Math.min(columns,map.columns));layer.data=next;}map.columns=columns;map.rows=rows;horizontal.setMax(Math.max(0,columns-28));vertical.setMax(Math.max(0,rows-20));}
        map.id=geometry.value("mapId");map.name=geometry.value("mapName");map.tileWidth=tileWidth;map.tileHeight=tileHeight;map.x=x;map.y=y;map.unitScale=unit;draw();
    }
    private void saveLayer(){if(active==null)return;double x=layerForm.number("layerX"),y=layerForm.number("layerY"),opacity=layerForm.number("opacity");if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(opacity)||opacity<0||opacity>1)throw new IllegalArgumentException("Deslocamento/opacidade inválidos.");active.name=layerForm.value("layerName");active.offsetX=x;active.offsetY=y;active.opacity=opacity;layers.refresh();draw();}
    private void addLayer(){saveLayer();var layer=new Game.TileLayer();layer.name="Camada "+(map.layers.size()+1);layer.data=new long[map.columns*map.rows];map.layers.add(layer);layers.getItems().add(layer);layers.getSelectionModel().select(layer);}
    private void deleteLayer(){map.layers.remove(active);layers.getItems().remove(active);if(!layers.getItems().isEmpty())layers.getSelectionModel().selectFirst();else active=null;draw();}
    private void moveLayer(int delta){int index=map.layers.indexOf(active),next=index+delta;if(index<0||next<0||next>=map.layers.size())return;Collections.swap(map.layers,index,next);layers.getItems().setAll(map.layers);layers.getSelectionModel().select(next);draw();}
    private void refreshTiles(){Integer old=brush.getValue(),selected=tiles.getValue();var ids=new ArrayList<>(map.tiles.keySet());Collections.sort(ids);tiles.getItems().setAll(ids);brush.getItems().setAll(ids);brush.getItems().addFirst(0);brush.setValue(old==null?0:old);if(selected!=null&&map.tiles.containsKey(selected))tiles.setValue(selected);}
    private ListCell<Integer> tileCell(){return new ListCell<>(){
        @Override protected void updateItem(Integer id,boolean empty){super.updateItem(id,empty);setGraphic(null);setText(empty||id==null?null:id==0?"Apagar":"Tile "+id);
            var tile=map.tiles.get(id);if(empty||tile==null||tile.assetPath.isBlank())return;Path path=assets.resolve(tile.assetPath,directory);if(path==null)return;var image=images.computeIfAbsent(tile.assetPath,key->new Image(path.toUri().toString()));if(image.isError())return;
            var view=new javafx.scene.image.ImageView(image);view.setViewport(new javafx.geometry.Rectangle2D(tile.sourceX,tile.sourceY,tile.width,tile.height));view.setFitWidth(32);view.setFitHeight(32);view.setSmooth(false);setGraphic(view);
        }
    };}
    private void loadTile(Integer id){activeTile=id;var tile=map.tiles.get(id);if(tile==null)return;tileForm.fields.get("asset").setText(tile.assetPath);tileForm.fields.get("sourceX").setText(""+tile.sourceX);tileForm.fields.get("sourceY").setText(""+tile.sourceY);tileForm.fields.get("width").setText(""+tile.width);tileForm.fields.get("height").setText(""+tile.height);}
    private void saveTile(){if(activeTile==null)return;var copy=new Game.Tile();copy.assetPath=tileForm.value("asset");Codec.validateAsset(copy.assetPath);copy.sourceX=Integer.parseInt(tileForm.value("sourceX"));copy.sourceY=Integer.parseInt(tileForm.value("sourceY"));copy.width=Integer.parseInt(tileForm.value("width"));copy.height=Integer.parseInt(tileForm.value("height"));if(copy.width<=0||copy.height<=0||copy.sourceX<0||copy.sourceY<0)throw new IllegalArgumentException("Recorte inválido.");map.tiles.put(activeTile,copy);images.clear();draw();}
    private void addTile(){saveTile();int id=map.tiles.keySet().stream().mapToInt(Integer::intValue).max().orElse(0)+1;var tile=new Game.Tile();tile.width=map.tileWidth;tile.height=map.tileHeight;map.tiles.put(id,tile);refreshTiles();tiles.setValue(id);}
    private void deleteTile(){if(activeTile==null)return;int id=activeTile;for(var layer:map.layers)for(long gid:layer.data)if((gid&0x0fffffffL)==id)throw new IllegalArgumentException("Esse tile está em uso; apague suas células primeiro.");map.tiles.remove(id);activeTile=null;refreshTiles();if(!tiles.getItems().isEmpty())tiles.getSelectionModel().selectFirst();draw();}
    private void importImage(){if(activeTile==null)return;var chooser=new FileChooser();chooser.setTitle("Imagem do tile");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("Imagens","*.png","*.jpg","*.jpeg"));try{var dir=RecentProject.imageDirectoryPreference().lastSaved();if(dir!=null&&Files.isDirectory(dir))chooser.setInitialDirectory(dir.toFile());}catch(Exception ignored){}var file=chooser.showOpenDialog(owner);if(file==null)return;try{tileForm.fields.get("asset").setText(assets.stage(file.toPath()));var imported=new Image(file.toURI().toString());if(imported.isError())throw new IllegalArgumentException("Imagem inválida");tileForm.fields.get("sourceX").setText("0");tileForm.fields.get("sourceY").setText("0");tileForm.fields.get("width").setText(""+(int)imported.getWidth());tileForm.fields.get("height").setText(""+(int)imported.getHeight());RecentProject.imageDirectoryPreference().rememberSaved(file.toPath().getParent());saveTile();}catch(Exception e){message.setText(e.getMessage());}}
    private void paint(double x,double y,boolean erase){if(active==null)return;int col=(int)Math.floor(x/20-active.offsetX/map.tileWidth)+(int)horizontal.getValue(),row=(int)Math.floor(y/20-active.offsetY/map.tileHeight)+(int)vertical.getValue();if(x<0||y<0||col<0||row<0||col>=map.columns||row>=map.rows)return;long gid=erase?0:brush.getValue()==null?0:brush.getValue();if(gid!=0){if(flipH.isSelected())gid|=0x80000000L;if(flipV.isSelected())gid|=0x40000000L;if(diagonal.isSelected())gid|=0x20000000L;}active.data[row*map.columns+col]=gid;draw();}
    private void draw(){var g=canvas.getGraphicsContext2D();g.setImageSmoothing(false);g.setFill(Color.web("#172638"));g.fillRect(0,0,560,400);int startX=(int)horizontal.getValue(),startY=(int)vertical.getValue();
        for(var layer:map.layers)for(int y=0;y<20&&y+startY<map.rows;y++)for(int x=0;x<28&&x+startX<map.columns;x++){long gid=layer.data[(y+startY)*map.columns+x+startX];var tile=map.tiles.get((int)(gid&0x0fffffffL));if(tile==null||tile.assetPath.isBlank())continue;Path path=assets.resolve(tile.assetPath,directory);if(path==null)continue;Image image=images.computeIfAbsent(tile.assetPath,key->new Image(path.toUri().toString()));if(image.isError())continue;double h=(gid&0x80000000L)!=0?-1:1,v=(gid&0x40000000L)!=0?-1:1;boolean diag=(gid&0x20000000L)!=0;g.save();g.setGlobalAlpha(layer.opacity);double width=tile.width*20.0/map.tileWidth,height=tile.height*20.0/map.tileHeight;g.translate(x*20+layer.offsetX*20/map.tileWidth+width/2,y*20+layer.offsetY*20/map.tileHeight+20-height/2);g.transform(diag?0:h,diag?v:0,diag?h:0,diag?0:v,0,0);g.drawImage(image,tile.sourceX,tile.sourceY,tile.width,tile.height,-width/2,-height/2,width,height);g.restore();}
        g.setStroke(Color.web("#ffffff30"));for(int x=0;x<=28;x++)g.strokeLine(x*20,0,x*20,400);for(int y=0;y<=20;y++)g.strokeLine(0,y*20,560,y*20);
    }
}
